USE `u345974778_donturron`;

CREATE TABLE IF NOT EXISTS dt_product_content (
  product_id VARCHAR(96) NOT NULL,
  category VARCHAR(64) NOT NULL,
  category_label VARCHAR(100) NOT NULL,
  subtitle VARCHAR(250) NOT NULL,
  description TEXT NOT NULL,
  features_json LONGTEXT NOT NULL,
  images_json LONGTEXT NOT NULL,
  art VARCHAR(64) NOT NULL,
  badge VARCHAR(80) NULL,
  manufacturer_brand VARCHAR(100) NULL,
  sort_order INT UNSIGNED NOT NULL DEFAULT 100,
  content_version INT UNSIGNED NOT NULL DEFAULT 1,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (product_id),
  KEY idx_dt_content_category_sort (category,sort_order),
  CONSTRAINT fk_dt_content_product FOREIGN KEY (product_id)
    REFERENCES dt_products(product_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT chk_dt_content_features_json CHECK (JSON_VALID(features_json)),
  CONSTRAINT chk_dt_content_images_json CHECK (JSON_VALID(images_json))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
INSERT INTO dt_product_content
 (product_id,category,category_label,subtitle,description,features_json,images_json,art,badge,manufacturer_brand,sort_order)
VALUES
('humidor-viaje-5-puros','humidores','Humidores','Para llevar hasta cinco puros.','Este humidor de viaje guarda hasta cinco puros. Su caja de plástico duradero tiene un humidificador incorporado y un interior acolchado para llevarlos organizados. Los puros y accesorios de ambientación de las fotografías no están incluidos.','["Capacidad anunciada: hasta 5 puros","Humidificador incorporado","Caja de plástico duradero"]','[{"src":"assets/products/humidor-viaje-interior.webp","label":"Interior abierto"},{"src":"assets/products/humidor-viaje-medidas.webp","label":"Estuche cerrado y medidas ilustrativas"},{"src":"assets/products/humidor-viaje-detalles.webp","label":"Cierres y humidificador"},{"src":"assets/products/humidor-viaje-ambientado.webp","label":"Vista ambientada"}]','humidor','NUEVA PIEZA',NULL,2),
('cenicero-mesa','ceniceros','Ceniceros','Cenicero y tres herramientas de corte.','Este set incluye un cenicero portátil de cerámica, una guillotina, un cortador en V y un punzón (punch). Las herramientas de corte tienen componentes de acero inoxidable. El puro de las fotografías se muestra como ejemplo y no está incluido.','["Cenicero portátil de cerámica","Guillotina y cortador en V con componentes de acero inoxidable","Punzón (punch) para puros"]','[{"src":"assets/products/set-portatil-conjunto.webp","label":"Vista del conjunto completo"},{"src":"assets/products/set-portatil-herramientas.webp","label":"Guillotina, cortador en V y punzón"},{"src":"assets/products/set-portatil-cenicero.webp","label":"Cenicero portátil de cerámica en uso; puro no incluido"},{"src":"assets/products/set-portatil-punzon.webp","label":"Detalle del punzón (punch)"},{"src":"assets/products/set-portatil-cortador-v.webp","label":"Detalle del cortador en V"}]','ashtray','NUEVA PIEZA',NULL,3),
('estuche-viaje','estuches','Estuches','Para guardar tus puros cuando viajas.','Este estuche con cremallera permite llevar hasta seis puros. Incluye un humidificador con esponja para ayudar a conservar la humedad. El proveedor lo describe como impermeable, pero todavía no contamos con una clasificación verificada de resistencia al agua. Los puros de las fotos no están incluidos.','["Capacidad anunciada: hasta 6 puros","Humidificador con esponja incluida","Estuche descrito como impermeable; clasificación no verificada"]','[{"src":"assets/products/estuche-6-interior.webp","label":"Interior con separador y humidificador; puros no incluidos"},{"src":"assets/products/estuche-6-cerrado.webp","label":"Estuche cerrado y disco humidificador"},{"src":"assets/products/estuche-6-humidificador.webp","label":"Vista explicativa del humidificador"},{"src":"assets/products/estuche-6-cuidado.webp","label":"Recomendación visual para humedecer la esponja"},{"src":"assets/products/estuche-6-cierre.webp","label":"Detalle del cierre de cremallera"}]','case','NUEVA PIEZA',NULL,4),
('estuche-kit-viaje','estuches','Estuches','Para llevar puros y accesorios.','Estuche portátil con acabado negro texturizado y cierre de cremallera. Tiene espacio para llevar entre cuatro y ocho puros, según su tamaño, y organizar accesorios. Los elementos de las fotografías son ilustrativos; aún falta confirmar cuáles accesorios, si los hay, se incluyen con el estuche.','["Capacidad anunciada: entre 4 y 8 puros, según formato","Estuche con cierre de cremallera","Espacio para organizar accesorios; contenido incluido por confirmar"]','[{"src":"assets/products/estuche-set-lounge.webp","label":"Estuche portátil y accesorios en cigar lounge; composición ilustrativa"},{"src":"assets/products/estuche-set-medidas.webp","label":"Lámina técnica con medidas indicativas de estuche y accesorios"}]','set','NUEVA PIEZA',NULL,5),
('reposa-puros-plegable','soportes','Soportes','Un lugar para apoyar tu puro.','Este soporte de acero inoxidable permite apoyar el puro mientras haces una pausa. Su diseño plegable en forma de X facilita guardarlo y llevarlo contigo. Está disponible en dos acabados: plata y negro.','["Fabricado en acero inoxidable","Diseño portátil y plegable","Acabados disponibles: plata y negro"]','[{"src":"assets/products/reposa-puros-dos-acabados.webp","label":"Versiones plata y negro sobre fondo mineral oscuro"},{"src":"assets/products/reposa-puros-plata.webp","label":"Reposa puros plegable de acero inoxidable en plata"},{"src":"assets/products/reposa-puros-negro.webp","label":"Reposa puros plegable de acero inoxidable en negro"}]','stand','NUEVA PIEZA',NULL,6),
('cortador-v-geometrico','cortadores','Cortadores','Una pieza compacta para preparar el corte.','Cortapuros metálico de corte en V con superficie de relieve geométrico tridimensional. Su mecanismo de accionamiento por pulsación permite preparar el corte con un solo movimiento. Diseño compacto disponible en acabados plateado y dorado.','["Cuchilla para corte en V","Mecanismo accionado mediante pulsación","Cuerpo metálico con relieve geométrico tridimensional","Acabados: plateado y dorado","Dimensiones de referencia del proveedor: 50.5 × 42 × 14.5 mm"]','[{"src":"assets/products/cortador-v-plateado.webp","label":"Cortapuros en V, acabado plateado sobre fondo oscuro"},{"src":"assets/products/cortador-v-dorado.webp","label":"Cortapuros en V, acabado dorado sobre fondo oscuro"},{"src":"assets/products/cortador-v-medidas.webp","label":"Dimensiones ilustrativas del cortapuros; medición del proveedor"},{"src":"assets/products/cortador-v-mecanismo.webp","label":"Mecanismo abierto y geometría de corte en V"},{"src":"assets/products/cortador-v-uso.webp","label":"Demostración de uso del cortapuros; puro ilustrativo no incluido"}]','cutter','PRÓXIMAMENTE',NULL,7),
('encendedor-sarike-butano','encendedores','Encendedores','Flama suave y jet en una sola pieza.','Encendedor metálico Parike de butano con diseño compacto y detalles de acabado texturizado. Permite alternar entre una flama suave (tradicional) y una flama jet (azul concentrada) mediante el control lateral. Disponible en acabados plata y dorado.','["Combustible: gas butano","Dos modos de flama: suave y jet (azul), con control lateral","Carcasa metálica con acabado texturizado","Dimensiones anunciadas: 61 × 38 × 13 mm; peso anunciado: 89 g","Acabados: plata y dorado"]','[{"src":"assets/products/encendedor-parike-plata.webp","label":"Encendedor Parike con acabado plateado, vista frontal"},{"src":"assets/products/encendedor-parike-dorado.webp","label":"Encendedor Parike con acabado dorado, vista frontal"},{"src":"assets/products/encendedor-parike-ambos-acabados.webp","label":"Encendedor Parike de doble llama: acabados plateado y dorado"},{"src":"assets/products/encendedor-sarike-modos-llama.webp","label":"Ilustración de los dos modos de flama: suave y jet"}]','lighter','PRÓXIMAMENTE',NULL,8),
('encendedor-honest-punch','encendedores','Encendedores','Doble flama jet y cortador punch en una sola pieza.','Encendedor metálico HONEST recargable con gas butano, con dos flamas tipo jet y cortador punch integrado para preparar la punta del puro. Su diseño compacto combina acabado metálico con panel decorativo y se presenta en colores negro y rojo.','["Dos flamas jet para el encendido","Cortador punch integrado y desplegable","Recargable con gas butano","Cuerpo metálico con panel frontal decorativo","Acabados: negro y rojo"]','[{"src":"assets/products/encendedor-honest-negro.webp","label":"Encendedor HONEST, acabado negro de textura cuadriculada"},{"src":"assets/products/encendedor-honest-rojo.webp","label":"Encendedor HONEST, acabado rojo con líneas decorativas"},{"src":"assets/products/encendedor-honest-doble-llama.webp","label":"Doble llama jet azul del encendedor HONEST en uso"},{"src":"assets/products/encendedor-honest-punch-mecanismo.webp","label":"Ilustración del mecanismo desplegable del cortador punch"},{"src":"assets/products/encendedor-honest-punch-7-5mm.webp","label":"Detalle de uso del cortador punch integrado, referencia ilustrativa"}]','lighter','PRÓXIMAMENTE','HONEST',9)
ON DUPLICATE KEY UPDATE product_id=product_id;
